'use strict';
const KEY = 'cheongna-steam-daily-v1';
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const stageNames = ['자료 조사','설계','제작','실험','분석','개선','발표 준비'];
const materialNames = ['Color Sensor','Distance Sensor','Force Sensor','Medium Angular Motor','Large Angular Motor','SMART Hub','Light Matrix','Wheel and Axle','LEGO Part','Gears'];
const pageIds = ['cover','plan','record','reflect','photos','satisfaction'];
const questions = ['오늘 어떤 주제를 탐구하나요?','무엇을 알아보고 싶고, 어떤 결과를 예상하나요?','관찰한 사실과 내 생각을 구분했나요?','결과의 근거는 무엇이고 다음에는 무엇을 바꿀까요?','사진만 보고도 내가 한 활동을 알 수 있나요?','수업의 재미, 이해도, 나의 참여는 어땠나요?'];
let state = emptyState();
let stream = null, cameraEpoch = 0, facing = 'user', activePage = 'cover', photoBusy = false, attachmentBusy = false, cameraSlot = null;
function today(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function emptyState(){return {format:'cheongna-steam-daily',version:1,fields:{date:today()},stages:[],materials:[],attachments:[],measurements:[{},{},{}],photos:[]}}
function normalize(data){
 if(data?.format!=='cheongna-steam-daily'||data.version!==1||!data.fields||typeof data.fields!=='object'||Array.isArray(data.fields)||!Array.isArray(data.photos)||!Array.isArray(data.stages)||!Array.isArray(data.measurements))throw Error('올바른 일일탐구일지 파일이 아닙니다.');
 const s=emptyState();
 for(const [k,v] of Object.entries(data.fields))if(typeof v==='string'&&!['__proto__','constructor','prototype'].includes(k))s.fields[k]=v.slice(0,100000);
 if(!CURRICULUM[s.fields.level]){s.fields.level='';s.fields.group='';s.fields.course=''}
 if(!CURRICULUM[s.fields.level]?.[s.fields.group]){s.fields.group='';s.fields.course=''}
 if(!CURRICULUM[s.fields.level]?.[s.fields.group]?.includes(s.fields.course))s.fields.course='';
 s.stages=data.stages.filter(v=>stageNames.includes(v));
 s.measurements=data.measurements.slice(0,100).filter(x=>x&&typeof x==='object').map(r=>Object.fromEntries(['condition','value','note'].map(k=>[k,typeof r[k]==='string'?r[k].slice(0,10000):''])));
 s.photos=data.photos.slice(0,4).map(p=>{if(p===null)return null;if(!p||typeof p.src!=='string'||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.src)||p.src.length>2500000)throw Error('사진 데이터가 올바르지 않습니다.');return {src:p.src,caption:typeof p.caption==='string'?p.caption.slice(0,1000):''}});
 s.materials=Array.isArray(data.materials)?data.materials.filter(v=>materialNames.includes(v)):materialNames.filter(v=>(s.fields.materials||'').includes(v));
 s.attachments=Array.isArray(data.attachments)?data.attachments.slice(0,30).map(a=>{if(!a||typeof a.name!=='string'||typeof a.data!=='string'||!/^data:[^,]*;base64,[A-Za-z0-9+/=]*$/.test(a.data)||a.data.length>14*1024*1024)throw Error('첨부 파일 형식이 올바르지 않습니다.');return {name:a.name.slice(0,250),data:a.data,image:/^data:image\/(jpeg|png|webp);base64,/.test(a.data)||(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(a.preview||'')&&(a.preview||'').length<2500000),preview:/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(a.preview||'')&&(a.preview||'').length<2500000?a.preview:'',size:Math.ceil((a.data.split(',')[1]||'').length*3/4)}}):[];
 if(s.attachments.reduce((n,a)=>n+a.size,0)>31*1024*1024)throw Error('첨부 용량이 너무 큽니다.');
 if(!/^[1-5]$/.test(s.fields.satisfaction||''))s.fields.satisfaction='';
 for(const key of ['enjoyment','understanding','participation'])if(!/^[1-5]$/.test(s.fields[key]||''))s.fields[key]='';
 return s;
}
try{const saved=localStorage.getItem(KEY);if(saved)state=normalize(JSON.parse(saved))}catch{ $('#saveState').textContent='저장된 일지를 불러오지 못했어요.' }
let database=null, saveSequence=0;
async function loadDatabase(){try{database=await new Promise((resolve,reject)=>{const request=indexedDB.open('cheongna-steam-journal',1);request.onupgradeneeded=()=>request.result.createObjectStore('notes');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('다른 창의 저장 연결을 닫아 주세요.'))});const saved=await new Promise((resolve,reject)=>{const r=database.transaction('notes').objectStore('notes').get(KEY);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});if(saved)state=normalize(saved)}catch{$('#saveState').textContent='기기 저장을 사용할 수 없으면 내보내기로 보관해 주세요.'}}
function save(){const sequence=++saveSequence;if(database){$('#saveState').textContent='저장 중';try{const tx=database.transaction('notes','readwrite');tx.objectStore('notes').put(state,KEY);tx.oncomplete=()=>{if(sequence===saveSequence)$('#saveState').textContent='이 기기에 저장됨'};tx.onerror=()=>{$('#saveState').textContent='저장 실패 · 내보내기로 보관해 주세요'};return true}catch{}}try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveState').textContent='이 기기에 저장됨';return true}catch{$('#saveState').textContent='저장 공간 부족 · 내보내기로 보관해 주세요';return false}}

function options(el,items,placeholder,value){el.replaceChildren(new Option(placeholder,''),...items.map(v=>new Option(v,v)));el.value=value||'';el.disabled=items.length===0}
function courses(){
 options($('#group'),Object.keys(CURRICULUM[state.fields.level]||{}),'그룹 선택',state.fields.group);
 options($('#course'),CURRICULUM[state.fields.level]?.[state.fields.group]||[],'주제 선택',state.fields.course);
 $('#curriculumHint').textContent=COURSE_DESCRIPTIONS[state.fields.level]||'STEAM-L1 또는 STEAM-L2를 선택하면 해당 그룹과 교육 주제를 선택할 수 있어요.';
 $('#selectedCourse').textContent=[state.fields.level,state.fields.group,state.fields.course].filter(Boolean).join(' / ')||'기본 정보에서 교육과정을 선택해 주세요.';
}
function hydrate(){for(const el of $$('[data-key]'))el.value=state.fields[el.dataset.key]||'';courses();for(const el of $$('[data-stage]'))el.checked=state.stages.includes(el.value);for(const el of $$('[data-material]'))el.checked=state.materials.includes(el.value);renderMeasures();renderPhotos();renderAttachments();renderRating();progress()}
function progress(){const fields=$$('[data-track]');const n=fields.filter(el=>el.value.trim()).length+(state.materials.length?1:0);const percent=Math.round(n/(fields.length+1)*100);$('#progressLabel').textContent=percent+'% 작성';$('#progressBar').style.width=$('#sideProgress').style.width=percent+'%'}
function switchPage(id){if(!pageIds.includes(id))return;if(id!=='photos')closeCamera();activePage=id;$$('.page').forEach(el=>el.classList.toggle('active',el.id===id));$$('[data-target]').forEach(el=>{el.classList.toggle('active',el.dataset.target===id);el.setAttribute('aria-current',el.dataset.target===id?'step':'false')});$('#stepName').textContent=$('#'+id+' h2').textContent;$('#focusQuestion').textContent=questions[pageIds.indexOf(id)];$('#pageCounter').textContent=(pageIds.indexOf(id)+1)+' / '+pageIds.length;window.scrollTo({top:0,behavior:'smooth'})}
for(const name of stageNames){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=name;input.dataset.stage='true';label.append(input,document.createTextNode(name));$('#stages').append(label);input.addEventListener('change',()=>{state.stages=$$('[data-stage]:checked').map(el=>el.value);save()})}
$$('[data-target],[data-next]').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.target||b.dataset.next)));
document.addEventListener('input',event=>{const el=event.target;if(!el.matches('[data-key]'))return;state.fields[el.dataset.key]=el.value;if(el.id==='level'){state.fields.group='';state.fields.course='';courses()}else if(el.id==='group'){state.fields.course='';courses()}else if(el.id==='course')courses();save();progress()});
function renderMeasures(){const body=$('#measureRows');body.replaceChildren();state.measurements.forEach((row,i)=>{const tr=document.createElement('tr');const number=document.createElement('td');number.textContent=i+1;tr.append(number);for(const [key,label] of [['condition','조건 / 측정 항목'],['value','측정값 · 단위'],['note','관찰 메모']]){const td=document.createElement('td'),input=document.createElement('input');input.value=row[key]||'';input.setAttribute('aria-label',(i+1)+'회차 '+label);input.addEventListener('input',()=>{row[key]=input.value;save()});td.append(input);tr.append(td)}const td=document.createElement('td'),del=document.createElement('button');td.className='no-print';del.textContent='삭제';del.setAttribute('aria-label',(i+1)+'회차 삭제');del.onclick=()=>{state.measurements.splice(i,1);renderMeasures();save()};td.append(del);tr.append(td);body.append(tr)})}
$('#addMeasure').onclick=()=>{if(state.measurements.length>=100)return;state.measurements.push({});renderMeasures();save()};
function renderPhotos(){const grid=$('#photoGrid');grid.replaceChildren();for(let i=0;i<4;i++){const p=state.photos[i],card=document.createElement('figure'),area=document.createElement('div'),caption=document.createElement('figcaption');card.className='photo-card';area.className='photo-image';if(p){const img=new Image();img.src=p.src;img.alt=p.caption||'학습 모습 '+(i+1);area.append(img);const del=document.createElement('button');del.textContent='삭제';del.setAttribute('aria-label',(i+1)+'번 사진 삭제');del.onclick=()=>{state.photos[i]=null;renderPhotos();save()};caption.append(document.createTextNode((i+1)+'번째 기록'),del);const label=document.createElement('label'),input=document.createElement('input');label.append(document.createTextNode('사진 설명'));input.value=p.caption;input.maxLength=1000;input.placeholder='무엇을 하고 있나요?';input.addEventListener('input',()=>{p.caption=input.value;img.alt=input.value||'학습 모습 '+(i+1);save()});label.append(input);caption.append(label)}else{const placeholder=document.createElement('div'),n=document.createElement('b');placeholder.className='photo-placeholder';n.textContent=String(i+1).padStart(2,'0');placeholder.append(n,document.createTextNode('학습 사진'));area.append(placeholder);caption.textContent='촬영하거나 사진을 선택해 주세요.'}const capture=document.createElement('button');capture.className='slot-camera tool-button';capture.textContent=p?'다시 촬영':'카메라로 촬영';capture.setAttribute('aria-label',(i+1)+'번 사진 '+capture.textContent);capture.onclick=()=>openDeviceCamera(i);area.append(capture);card.append(area,caption);grid.append(card)}$('#photoCount').textContent=state.photos.filter(Boolean).length+' / 4컷';$('#takePhoto').disabled=(cameraSlot===null&&state.photos.filter(Boolean).length>=4)||!stream||!$('#cameraVideo').videoWidth}
function closeCamera(){cameraEpoch++;cameraSlot=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#cameraVideo').srcObject=null;if($('#cameraDialog').open)$('#cameraDialog').close();$('#takePhoto').disabled=true}
async function startCamera(){const epoch=++cameraEpoch;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#cameraVideo').srcObject=null;$('#takePhoto').disabled=true;$('#cameraStatus').textContent='카메라를 준비하고 있어요.';try{if(!navigator.mediaDevices?.getUserMedia)throw Error('unsupported');const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:facing},width:{ideal:1280},height:{ideal:960}},audio:false});if(epoch!==cameraEpoch||!$('#cameraDialog').open){next.getTracks().forEach(t=>t.stop());return}stream=next;$('#cameraVideo').srcObject=stream;await $('#cameraVideo').play();if(epoch!==cameraEpoch)return;$('#takePhoto').disabled=!$('#cameraVideo').videoWidth;$('#cameraStatus').textContent='화면을 확인하고 사진 찍기를 눌러 주세요.'}catch(e){if(epoch!==cameraEpoch)return;$('#cameraStatus').textContent=e.name==='NotAllowedError'?'카메라 권한을 허용해 주세요. 닫은 뒤 사진 파일 선택으로도 넣을 수 있어요.':e.name==='NotFoundError'?'연결된 카메라가 없어요. 사진 파일 선택을 이용해 주세요.':'카메라를 열지 못했어요. HTTPS 또는 localhost에서 열고 카메라 연결을 확인해 주세요. 사진 파일 선택으로도 넣을 수 있어요.'}}
function openDeviceCamera(slot){cameraSlot=slot;facing='user';if(!$('#cameraDialog').open)$('#cameraDialog').showModal();startCamera()}
$('#closeCamera').onclick=closeCamera;$('#cameraDialog').addEventListener('cancel',e=>{e.preventDefault();closeCamera()});$('#flipCamera').onclick=()=>{facing=facing==='user'?'environment':'user';startCamera()};$('#cameraVideo').addEventListener('loadeddata',()=>{$('#takePhoto').disabled=!stream||(cameraSlot===null&&state.photos.filter(Boolean).length>=4)});
function makePhoto(source,width,height){const scale=Math.min(1,1000/Math.max(width,height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);return {src:canvas.toDataURL('image/jpeg',0.78),caption:''}}
$('#takePhoto').onclick=()=>{const video=$('#cameraVideo');if(!stream||!video.videoWidth||(cameraSlot===null&&state.photos.filter(Boolean).length>=4))return;state.photos[cameraSlot??nextPhotoSlot()]=makePhoto(video,video.videoWidth,video.videoHeight);renderPhotos();save();$('#cameraStatus').textContent=state.photos.filter(Boolean).length+' / 4컷 촬영했어요.';$('#photoStatus').textContent='사진을 추가했어요. 아래에서 설명을 적어 주세요.';closeCamera()};
async function uploadPhotos(event){const files=[...event.target.files];event.target.value='';if(photoBusy)return;photoBusy=true;let added=0,failed=0,skipped=0;try{for(const file of files){if(state.photos.filter(Boolean).length>=4){skipped++;continue}if(!file.type.startsWith('image/')||file.size>20*1024*1024){failed++;continue}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(state.photos.filter(Boolean).length>=4){skipped++;continue}state.photos[nextPhotoSlot()]=makePhoto(img,img.naturalWidth,img.naturalHeight);added++;renderPhotos();save()}catch{failed++}finally{URL.revokeObjectURL(url)}}$('#photoStatus').textContent=[added?added+'장의 사진을 추가했어요.':'',failed?failed+'개 파일을 읽지 못했어요. 20MB 이하의 JPG·PNG 등 이미지로 선택해 주세요.':'',skipped?'사진은 최대 4컷까지 넣을 수 있어요. 기존 사진을 삭제하면 다시 추가할 수 있어요.':''].filter(Boolean).join(' ')}finally{photoBusy=false}}
$('#photoUpload').addEventListener('change',uploadPhotos);window.addEventListener('pagehide',closeCamera);document.addEventListener('visibilitychange',()=>{if(document.hidden)closeCamera()});
$('#exportData').onclick=()=>{save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=((state.fields.date||today())+'_'+(state.fields.name||'이름없음')+'_일일탐구일지').replace(/[\\/:*?"<>|]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#importData').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(photoBusy||attachmentBusy){alert('사진 처리가 끝난 후 가져와 주세요.');return}try{if(file.size>65*1024*1024)throw Error('65MB 이하의 일지 파일을 선택해 주세요.');const next=normalize(JSON.parse(await file.text()));if(!confirm('현재 작성 내용을 가져온 일지로 바꿀까요? 필요한 내용은 먼저 내보내기로 보관해 주세요.'))return;closeCamera();state=next;hydrate();save();switchPage('cover')}catch(e){alert(e.message||'파일을 불러오지 못했어요.')}});
$('#resetData').onclick=()=>{if(photoBusy||attachmentBusy){alert('사진과 파일 처리가 끝난 후 새 일지를 열어 주세요.');return}if(!confirm('새 일지를 시작할까요? 현재 내용과 사진이 지워집니다. 보관하려면 취소 후 내보내기를 눌러 주세요.'))return;closeCamera();state=emptyState();hydrate();save();$('#photoStatus').textContent='';switchPage('cover')};
function preparePrint(){cleanupPrint();$$('input:not([type=checkbox]):not([type=file]),textarea,select').forEach(el=>{const div=document.createElement('div');div.className='print-value';div.textContent=el.tagName==='SELECT'?(el.value||'미선택'):(el.value||' ');el.after(div)})}
function cleanupPrint(){$$('.print-value').forEach(el=>el.remove())}
window.addEventListener('beforeprint',preparePrint);window.addEventListener('afterprint',cleanupPrint);
document.body.inert=true;loadDatabase().finally(()=>{try{hydrate();switchPage('cover')}finally{document.body.inert=false}});

function nextPhotoSlot(){for(let i=0;i<4;i++)if(!state.photos[i])return i;return -1}
for(const name of materialNames){const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.value=name;input.dataset.material='true';label.append(input,document.createTextNode(name));$('#materialsChecklist').append(label);input.addEventListener('change',()=>{state.materials=$$('[data-material]:checked').map(el=>el.value);save();progress()})}
function renderAttachments(){const list=$('#attachmentList');list.replaceChildren();state.attachments.forEach((a,i)=>{const card=document.createElement('div');card.className='attachment-card';if(a.image){const img=new Image();img.src=a.preview||a.data;img.alt=a.name;card.append(img)}const name=document.createElement('strong');name.textContent=a.name;const actions=document.createElement('div');actions.className='photo-actions';const download=document.createElement('button');download.className='tool-button';download.textContent='파일 저장';download.onclick=async()=>{const raw=atob(a.data.split(',')[1]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));downloadBlob(new Blob([bytes],{type:'application/octet-stream'}),a.name)};const remove=document.createElement('button');remove.className='tool-button';remove.textContent='삭제';remove.setAttribute('aria-label',a.name+' 삭제');remove.onclick=()=>{state.attachments.splice(i,1);renderAttachments();save()};actions.append(download,remove);card.append(name,actions);list.append(card)})}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('파일 읽기 실패'));reader.readAsDataURL(file)})}
async function addAttachments(event){const files=[...event.target.files];event.target.value='';if(attachmentBusy)return;attachmentBusy=true;let added=0;const errors=[];try{for(const file of files){if(state.attachments.length>=30||file.size>10*1024*1024||state.attachments.reduce((n,a)=>n+a.size,0)+file.size>30*1024*1024){errors.push(file.name+': 용량 또는 30개 개수 제한 초과');continue}try{let data,preview='',image=false;if(event.target.id==='attachImages'||file.type.startsWith('image/')){const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();preview=makePhoto(img,img.naturalWidth,img.naturalHeight).src;data=await fileData(file);image=true}finally{URL.revokeObjectURL(url)}}else data=await fileData(file);state.attachments.push({name:file.name,data,preview,image,size:Math.ceil((data.split(',')[1]||'').length*3/4)});added++;renderAttachments();save()}catch{errors.push(file.name+': 읽을 수 없는 파일')}}$('#attachmentStatus').textContent=[added+'개 첨부 완료',...errors].join(' · ')}finally{attachmentBusy=false}}
$('#attachImages').addEventListener('change',addAttachments);$('#attachFiles').addEventListener('change',addAttachments);
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

const ratingDescriptions=['전혀 그렇지 않아요','별로 그렇지 않아요','보통이에요','그런 편이에요','매우 그래요'];
const ratingKeys=['enjoyment','understanding','participation'];
function renderRating(){for(const key of ratingKeys){const rating=Number(state.fields[key])||0;document.querySelectorAll('input[name="'+key+'"]').forEach(input=>{input.checked=Number(input.value)===rating;input.parentElement.classList.toggle('selected',Number(input.value)<=rating)});document.querySelector('#ratingText-'+key).textContent=rating?rating+' / 5점 · '+ratingDescriptions[rating-1]:'아직 선택하지 않았어요.';document.querySelector('#clearRating-'+key).disabled=!rating}}
for(const key of ratingKeys){document.querySelectorAll('input[name="'+key+'"]').forEach(input=>input.addEventListener('change',()=>{if(input.checked){state.fields[key]=input.value;renderRating();save()}}));document.querySelector('#clearRating-'+key).onclick=()=>{state.fields[key]='';renderRating();save()}}
